import struct, sys
def channels(path):
    b = open(path, "rb").read(65536)
    i = b.index(b"channels\0chlist\0") + len(b"channels\0chlist\0")
    size = struct.unpack("<i", b[i:i+4])[0]; v = b[i+4:i+4+size]; j = 0; out = {}
    while v[j] != 0:
        n = v[j:v.index(0, j)].decode(); j += len(n)+1
        out[n] = {0: "uint", 1: "half", 2: "float"}[struct.unpack("<i", v[j:j+4])[0]]; j += 16
    k = b.index(b"compression\0compression\0") + len(b"compression\0compression\0") + 4
    return b[k], out
for p in sys.argv[1:]:
    comp, ch = channels(p)
    passes = {}
    for n, t in ch.items(): passes.setdefault(n.rsplit(".", 1)[0].split(".", 1)[-1], set()).add(t)
    print(p.split("/")[-1], "compression", comp, {k: sorted(v) for k, v in passes.items()})
EOF
